<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Controllers\Api\V1\Concerns\ApiResponse; use App\Http\Resources\Api\V1\{RegionResource,CityResource,LevelResource}; use App\Models\{Region,City,Level,UserRegionProgress,UserCityProgress,UserLevelProgress}; use Illuminate\Http\Request;
class GameMapController extends Controller { use ApiResponse; private function attach($items,$type,$user){ $cls=['region'=>UserRegionProgress::class,'city'=>UserCityProgress::class,'level'=>UserLevelProgress::class][$type]; $key=$type.'_id'; $p=$cls::where('user_id',$user->id)->whereIn($key,$items->pluck('id'))->get()->keyBy($key); return $items->each(fn($i)=>$i->setRelation('progress',$p->get($i->id))); } public function map(Request $r){ $regions=Region::with(['cities'=>fn($q)=>$q->where('is_active',true)->orderBy('order'),'cities.levels'=>fn($q)=>$q->where('is_active',true)->orderBy('order')])->where('is_active',true)->orderBy('order')->get(); $this->attach($regions,'region',$r->user()); $cities=$regions->pluck('cities')->flatten(); $levels=$cities->pluck('levels')->flatten(); $this->attach($cities,'city',$r->user()); $this->attach($levels,'level',$r->user()); return $this->success('Carte du jeu.', RegionResource::collection($regions)); } public function showRegion(Region $region){ return $this->success('Région.', new RegionResource($region->load('cities.levels'))); } public function showCity(City $city){ return $this->success('Ville.', new CityResource($city->load('levels'))); } public function showLevel(Level $level){ return $this->success('Niveau.', new LevelResource($level)); }}
